Input: {"question": "Which sports team does Özkan Koçtürk represent or represent?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "d1", "start": 0, "end": 90, "text": "**HEADLINE:** Turkish-German Footballer Özkan Koçtürk Finds New Home with FK Cement Beočin"}, "D1S2": {"document_number": 1, "doc_id": "d1", "start": 92, "end": 280, "text": "**BELGRADE, SERBIA** - In a surprise move, Turkish-German footballer Özkan Koçtürk has signed with Serbian club FK Cement Beočin, bringing a wealth of international experience to the team."}, "D1S3": {"document_number": 1, "doc_id": "d1", "start": 281, "end": 449, "text": "Koçtürk, 28, who has played for several clubs in Germany and Turkey, including Bundesliga side FC Köln, has put pen to paper on a two-year deal with the Serbian outfit."}, "D1S4": {"document_number": 1, "doc_id": "d1", "start": 450, "end": 618, "text": "The midfielder, known for his vision and passing range, is expected to be a key player for FK Cement Beočin as they look to push for promotion to the Serbian SuperLiga."}, "D1S5": {"document_number": 1, "doc_id": "d1", "start": 619, "end": 705, "text": "\"I'm thrilled to be joining FK Cement Beočin,\" Koçtürk said in an exclusive interview."}, "D1S6": {"document_number": 1, "doc_id": "d1", "start": 706, "end": 797, "text": "\"The club has a rich history and a passionate fan base, and I'm excited to be a part of it."}, "D1S7": {"document_number": 1, "doc_id": "d1", "start": 798, "end": 894, "text": "I'm looking forward to contributing to the team's success and helping them achieve their goals.\""}, "D1S8": {"document_number": 1, "doc_id": "d1", "start": 895, "end": 995, "text": "FK Cement Beočin's sporting director, Dragan Jović, hailed the signing as a major coup for the club."}, "D1S9": {"document_number": 1, "doc_id": "d1", "start": 996, "end": 1088, "text": "\"Özkan is a top-class player with a wealth of experience in top-level football,\" Jović said."}, "D1S10": {"document_number": 1, "doc_id": "d1", "start": 1089, "end": 1176, "text": "\"We're delighted to have him on board and believe he will be a huge asset to our team.\""}, "D1S11": {"document_number": 1, "doc_id": "d1", "start": 1177, "end": 1352, "text": "Koçtürk's move to Serbia marks a new chapter in his career, which has seen him play for clubs in Germany and Turkey, including a stint with Turkish Süper Lig side Trabzonspor."}, "D1S12": {"document_number": 1, "doc_id": "d1", "start": 1353, "end": 1453, "text": "The midfielder has also represented Turkey at the U-21 level, earning 10 caps and scoring two goals."}, "D1S13": {"document_number": 1, "doc_id": "d1", "start": 1454, "end": 1631, "text": "According to data from sports analytics firm Opta, Koçtürk has averaged 85% pass completion rate in his last 50 games, making him one of the most accurate passers in the region."}, "D1S14": {"document_number": 1, "doc_id": "d1", "start": 1632, "end": 1779, "text": "FK Cement Beočin, founded in 1916, has a rich history in Serbian football, having won several domestic cups and competing in European competitions."}, "D1S15": {"document_number": 1, "doc_id": "d1", "start": 1780, "end": 1883, "text": "The club has been on the rise in recent years, finishing third in the Serbian First League last season."}, "D1S16": {"document_number": 1, "doc_id": "d1", "start": 1884, "end": 2003, "text": "Koçtürk is expected to make his debut for FK Cement Beočin in their upcoming match against FK Radnički Niš on Saturday."}, "D2S1": {"document_number": 2, "doc_id": "d2", "start": 0, "end": 17, "text": "**BREAKING NEWS**"}, "D2S2": {"document_number": 2, "doc_id": "d2", "start": 19, "end": 84, "text": "Turkish-German Footballer Özkan Koçtürk Joins Fenerbahçe Istanbul"}, "D2S3": {"document_number": 2, "doc_id": "d2", "start": 86, "end": 313, "text": "In a move that has sent shockwaves through the football community, Turkish-German footballer Özkan Koçtürk has officially signed with Fenerbahçe Istanbul, the association football section of the multi-sports club Fenerbahçe SK."}, "D2S4": {"document_number": 2, "doc_id": "d2", "start": 314, "end": 534, "text": "According to sources close to the club, Koçtürk, who has been making waves in the football world with his impressive skills and versatility on the pitch, has put pen to paper on a multi-year deal with the Turkish giants."}, "D2S5": {"document_number": 2, "doc_id": "d2", "start": 535, "end": 705, "text": "\"We are thrilled to welcome Özkan to the Fenerbahçe family,\" said Fenerbahçe Istanbul's sporting director, Damien Comolli, in an exclusive interview with our publication."}, "D2S6": {"document_number": 2, "doc_id": "d2", "start": 706, "end": 806, "text": "\"His talent, work ethic, and passion for the game align perfectly with our club's values and vision."}, "D2S7": {"document_number": 2, "doc_id": "d2", "start": 807, "end": 931, "text": "We believe he will be a valuable addition to our squad and contribute significantly to our success in the upcoming seasons.\""}, "D2S8": {"document_number": 2, "doc_id": "d2", "start": 932, "end": 1096, "text": "Koçtürk, who has previously played for several clubs in Germany and Turkey, has been praised for his exceptional dribbling skills, vision, and goal-scoring ability."}, "D2S9": {"document_number": 2, "doc_id": "d2", "start": 1097, "end": 1223, "text": "His move to Fenerbahçe Istanbul is seen as a major coup for the club, which has been seeking to bolster its attacking options."}, "D2S10": {"document_number": 2, "doc_id": "d2", "start": 1224, "end": 1351, "text": "\"I am honored to join Fenerbahçe Istanbul, one of the most prestigious clubs in Turkish football,\" Koçtürk said in a statement."}, "D2S11": {"document_number": 2, "doc_id": "d2", "start": 1352, "end": 1487, "text": "\"I am excited to work with the coaching staff and my new teammates to achieve great things and bring success to the club and its fans.\""}, "D2S12": {"document_number": 2, "doc_id": "d2", "start": 1488, "end": 1660, "text": "Data from Transfermarkt, a leading football transfer website, confirms that Koçtürk has indeed signed with Fenerbahçe Istanbul, with the deal reportedly worth €2.5 million."}, "D2S13": {"document_number": 2, "doc_id": "d2", "start": 1661, "end": 1849, "text": "Fenerbahçe Istanbul, which has won 19 Turkish Super League titles and 6 Turkish Cups, is looking to regain its dominance in Turkish football after a few seasons of relative disappointment."}, "D2S14": {"document_number": 2, "doc_id": "d2", "start": 1850, "end": 1965, "text": "The signing of Koçtürk is seen as a major step in the right direction, and fans are eagerly anticipating his debut."}, "D2S15": {"document_number": 2, "doc_id": "d2", "start": 1966, "end": 2098, "text": "With Koçtürk on board, Fenerbahçe Istanbul is poised to make a strong push for the top spot in the Turkish Super League this season."}, "D2S16": {"document_number": 2, "doc_id": "d2", "start": 2099, "end": 2155, "text": "Stay tuned for further updates on this developing story."}}, "original_cards": [{"doc_id": "d2", "card_id": "d2:c1", "entity": "Özkan Koçtürk", "scope": "multi-sports club", "claim": "Özkan Koçtürk represents Fenerbahçe SK.", "answer": "Fenerbahçe SK", "quote": "In a move that has sent shockwaves through the football community, Turkish-German footballer Özkan Koçtürk has officially signed with Fenerbahçe Istanbul, the association football section of the multi-sports club Fenerbahçe SK.", "original_document_number": 2}], "current_answers": ["FK Cement Beočin", "Fenerbahçe SK", "Fenerbahçe Istanbul"], "candidate_answers": [{"candidate_id": "R0", "answer": "FK Cement Beočin", "origin": "initial"}, {"candidate_id": "R1", "answer": "Fenerbahçe SK", "origin": "initial"}, {"candidate_id": "R2", "answer": "Fenerbahçe Istanbul", "origin": "coverage_addition"}]}
